"""The security state the core declares, against the engine: generated by the engine, copied into a profile, read by the first navigation.

A retail Firefox has, in `cert_storage`, the intermediates of the public web, OneCRL and the CRLite filters from its first second. The core downloads the three inputs
(`intermediates.json`, `onecrl.json`, `crlite.json` and the filter files) and does not write cert_storage itself: the engine has a GENERATE MODE, a launch whose profile
holds exactly four prefs (`zoom.stealth.securitystate.generate` and the paths of the three files), which imports them through its own code, writes
`<profile>/securitystate-result.json` and `<profile>/security_state/`, prints nothing and exits 0 only when the result says ok. A normal launch imports nothing: the core
copies a ready `security_state/` into the profile (`STEALTHFOX_SECURITY_STATE` names a ready directory), and Juggler hands the client nothing before cert_storage has read it.

What is proved here, on the engine in use:

  1. the engine, launched directly as the contract says, generates what it is given: the result has exactly the contract's keys and says the inputs' timestamps, channel
     and filter hashes, and `security_state/` holds the database and the bytes of the full filter and of the delta; the core's own validation (`generate`) passes on it;
  2. a normal launch declares no pref of the mode, leaves no result file and re-imports nothing (the filter and the delta in the profile are the ready directory's bytes);
  3. a certificate that Mozilla's CRLite test data say is revoked in a DELTA is refused at the FIRST navigation of the first page (SEC_ERROR_REVOKED_CERTIFICATE), and one that
     is not revoked loads. The same revoked certificate loads when the ready directory holds no data, so the refusal comes from the security state and from nothing else;
  4. a launch with a ready directory that has no `security_state/`, or an empty one, starts and loads a page.

The CRLite data are Mozilla's own test data (`security/manager/ssl/tests/unit/test_crlite_filters/`: the filters, and the certificates they say are revoked), in
`tests/data/security_state_crlite.json` (per file: Mozilla's path, sha256, base64; the sha256 is checked before use). The filters are keyed on the issuer's public key
and on the serial of the leaf (and on the timestamps of its SCTs), so the test builds, on every run, certificates that have the same issuer key (Mozilla's `int.pem` has no
key specification in its certspec: its key is the one `pykey.py` calls `default`, in `tests/data/security_state_default_key.json`) and the same serials and SCT
extensions as Mozilla's `revoked-in-delta.example.com.pem` and `valid.example.com.pem`, signed by a fresh root that the profile trusts and valid now. Everything is on loopback.
"""
from __future__ import annotations

import base64
import configparser
import datetime
import hashlib
import ipaddress
import json
import os
import ssl
import subprocess
import sys
import threading
from http.server import BaseHTTPRequestHandler
from pathlib import Path

import pytest

from _servers import LocalServer

pytestmark = pytest.mark.e2e

DATA = Path(__file__).resolve().parent / "data"

GENERATE_TIMEOUT_S = 120
PREF_GENERATE = "zoom.stealth.securitystate.generate"
PREF_INTERMEDIATES = "zoom.stealth.intermediates.file"
PREF_ONECRL = "zoom.stealth.onecrl.file"
PREF_CRLITE = "zoom.stealth.crlite.file"
MODE_PREFS = (PREF_GENERATE, PREF_INTERMEDIATES, PREF_ONECRL, PREF_CRLITE)
RESULT_NAME = "securitystate-result.json"
STATE_DIR = "security_state"
FULL = "20200101-0-filter"
DELTA = "20200101-1-filter.delta"
REVOKED_NAME = "revoked-in-delta.example.com.pem"
VALID_NAME = "valid.example.com.pem"
INTERMEDIATES_TS = 1763000000001
ONECRL_TS = 1763000000002
CRLITE_TS = 1763000000003
SEC_ERROR_REVOKED_CERTIFICATE = "SEC_ERROR_REVOKED_CERTIFICATE"
#: The result of a ready directory that holds no data (the one of the core's ci/security-state): a launch with it copies nothing.
RESULT_WITHOUT_DATA = {"format": 1, "ok": True, "error": None, "engine": {"version": "", "build_id": ""},
                       "collections": {"intermediates": {"collection_timestamp": 0}, "onecrl": {"collection_timestamp": 0},
                                       "cert-revocations": {"collection_timestamp": 0, "channel": "default"}},
                       "crlite_filter_hashes": []}


# --- the engine under test -------------------------------------------------------------------------------------------------------------------------------

@pytest.fixture(scope="module")
def ff(request):
    """The engine: STEALTHFOX_E2E_BINARY, else what the whole suite uses (INVPW_BINARY_PATH, or the cached one)."""
    declared = os.environ.get("STEALTHFOX_E2E_BINARY")
    if declared and os.path.exists(declared):
        return declared
    return request.getfixturevalue("firefox_binary")


def _application_ini(binary):
    parser = configparser.RawConfigParser()
    parser.read(str(Path(binary).parent / "application.ini"), encoding="utf-8")
    return parser["App"]["BuildID"], parser["App"]["Version"]


# --- processes ---------------------------------------------------------------------------------------------------------------------------------------------

def _kill_tree(proc):
    """The process and everything it started."""
    import psutil

    try:
        parent = psutil.Process(proc.pid)
        victims = parent.children(recursive=True) + [parent]
    except psutil.NoSuchProcess:
        return
    for victim in victims:
        try:
            victim.kill()
        except psutil.NoSuchProcess:
            pass
    proc.wait()


def _engine_env(work: Path) -> dict:
    """The environment of a direct launch of the engine: its per-user directories inside `work`, so that nothing is written outside it."""
    env = dict(os.environ)
    for variable, name in (("XDG_CONFIG_HOME", "xdg-config"), ("XDG_CACHE_HOME", "xdg-cache"), ("APPDATA", "appdata"), ("LOCALAPPDATA", "localappdata"),
                           ("HOME", "home"), ("TMP", "tmp"), ("TEMP", "tmp"), ("TMPDIR", "tmp")):
        directory = work / name
        directory.mkdir(exist_ok=True)
        env[variable] = str(directory)
    env["MOZ_CRASHREPORTER_DISABLE"] = "1"
    return env


def _run_to_the_end(argv, env, cwd, timeout_s):
    """Runs `argv` with nothing on stdout and stderr; (exit code, None) or (None, "timed out ...") with its whole tree ended."""
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) if sys.platform == "win32" else 0
    proc = subprocess.Popen(argv, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, env=env, cwd=str(cwd), creationflags=flags)
    try:
        try:
            return proc.wait(timeout=timeout_s), None
        except subprocess.TimeoutExpired:
            return None, "did not finish within %s s" % timeout_s
    finally:
        _kill_tree(proc)


# --- the files the core would write ----------------------------------------------------------------------------------------------------------------------------

def _crlite_data():
    return json.loads((DATA / "security_state_crlite.json").read_bytes().decode("utf-8"))["files"]


def _crlite_file(name):
    """The bytes of one of Mozilla's test files, after its sha256 is checked."""
    entry = _crlite_data()[name]
    raw = base64.b64decode(entry["base64"], validate=True)
    assert hashlib.sha256(raw).hexdigest() == entry["sha256"], "%s of tests/data/security_state_crlite.json is not the bytes it says" % name
    return raw


def _x509():
    from cryptography import x509
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.x509.oid import NameOID

    return x509, hashes, serialization, ec, NameOID


def _der(cert):
    return cert.public_bytes(_x509()[2].Encoding.DER)


def _b64(raw):
    return base64.b64encode(raw).decode("ascii")


def _utc(moment):
    return moment.strftime("%Y-%m-%dT%H:%M:%SZ")


def _a_few_intermediates(now):
    """Self-made certificates in the format of the core's list: a few, with the hash of each DER and its subject."""
    x509, hashes, _serialization, ec, name_oid = _x509()
    certs = []
    for n in range(3):
        key = ec.generate_private_key(ec.SECP256R1())
        name = x509.Name([x509.NameAttribute(name_oid.COMMON_NAME, "Security State Test Intermediate %d" % n)])
        cert = (x509.CertificateBuilder().subject_name(name).issuer_name(name).public_key(key.public_key()).serial_number(x509.random_serial_number())
                .not_valid_before(now - datetime.timedelta(days=1)).not_valid_after(now + datetime.timedelta(days=30))
                .add_extension(x509.BasicConstraints(ca=True, path_length=0), critical=True).sign(key, hashes.SHA256()))
        raw = _der(cert)
        certs.append({"derHash": _b64(hashlib.sha256(raw).digest()), "cert": _b64(raw), "subject": _b64(name.public_bytes())})
    certs.sort(key=lambda c: c["derHash"])
    return certs


def _make_inputs(directory):
    """The three files the core declares and the two filter files, in `directory`: `Inputs`."""
    from invisible_core._security_state_generate import Inputs

    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    certs = _a_few_intermediates(now)
    intermediates = {"format": 1, "collection": "security-state/intermediates", "collection_timestamp": INTERMEDIATES_TS, "fetched_utc": _utc(now),
                     "count": len(certs), "set_sha256": hashlib.sha256("\n".join(sorted(c["derHash"] for c in certs)).encode("ascii")).hexdigest(), "certs": certs}
    onecrl = {"format": 1, "collection": "onecrl", "collection_timestamp": ONECRL_TS, "updated_utc": _utc(now),
              "revocations": [{"issuerName": _b64(hashlib.sha256(b"issuer-%d" % n).digest()), "serialNumber": _b64(hashlib.sha256(b"serial-%d" % n).digest()[:16])} for n in range(3)]
              + [{"subject": _b64(hashlib.sha256(b"subject").digest()), "pubKeyHash": _b64(hashlib.sha256(b"key").digest())}]}
    parts = {}
    for name in (FULL, DELTA):
        raw = _crlite_file(name)
        (directory / name).write_bytes(raw)
        parts[name] = {"file": name, "sha256": hashlib.sha256(raw).hexdigest(), "size": len(raw)}
    crlite = {"format": 1, "collection": "cert-revocations", "channel": "default", "collection_timestamp": CRLITE_TS, "updated_utc": _utc(now),
              "full": parts[FULL], "deltas": [parts[DELTA]]}
    for file_name, document in (("intermediates.json", intermediates), ("onecrl.json", onecrl), ("crlite.json", crlite)):
        (directory / file_name).write_bytes(json.dumps(document, separators=(",", ":")).encode("utf-8"))
    return Inputs(directory / "intermediates.json", directory / "onecrl.json", directory / "crlite.json")


@pytest.fixture(scope="module")
def inputs(tmp_path_factory):
    """The inputs of the generate mode, made once for the module."""
    return _make_inputs(tmp_path_factory.mktemp("security-state-inputs"))


# --- the generation ----------------------------------------------------------------------------------------------------------------------------------------

def _user_js(inputs) -> bytes:
    """EXACTLY the four prefs of the contract."""
    lines = ['user_pref("%s", true);' % PREF_GENERATE]
    for pref, path in ((PREF_INTERMEDIATES, inputs.intermediates), (PREF_ONECRL, inputs.onecrl), (PREF_CRLITE, inputs.crlite)):
        lines.append("user_pref(%s, %s);" % (json.dumps(pref), json.dumps(str(Path(path).resolve()))))
    return ("\n".join(lines) + "\n").encode("utf-8")


_READY = {}


def _ready(ff, inputs, root):
    """The ready directory the CORE makes from the inputs with the engine (its validation included), made once for the module; a failure is kept and said again."""
    from invisible_core._security_state_generate import default_argv, engine_id_of, generate

    if "state" not in _READY:
        out = Path(root) / "ready"
        try:
            generate(default_argv(ff), inputs, engine_id_of(ff), out)
            _READY["state"] = (out, None)
        except Exception as exc:
            _READY["state"] = (None, exc)
    out, error = _READY["state"]
    if error is not None:
        raise error
    return out


def _a_ready_directory_with(root, name, *, state):
    """A ready directory with the result only (`state` None) or with an empty `security_state/` (`state` "empty")."""
    directory = Path(root) / name
    directory.mkdir()
    (directory / RESULT_NAME).write_bytes(json.dumps(RESULT_WITHOUT_DATA, separators=(",", ":")).encode("utf-8"))
    if state == "empty":
        (directory / STATE_DIR).mkdir()
    return directory


def test_the_engine_generates_the_security_state_it_is_given(ff, inputs, tmp_path_factory):
    files = inputs
    work = tmp_path_factory.mktemp("generate")
    profile = work / "profile"
    profile.mkdir()
    (profile / "user.js").write_bytes(_user_js(files))
    code, why = _run_to_the_end([ff, "-headless", "-no-remote", "-profile", str(profile)], _engine_env(work), work, GENERATE_TIMEOUT_S)
    said = (profile / RESULT_NAME).read_bytes().decode("utf-8") if (profile / RESULT_NAME).is_file() else "no %s" % RESULT_NAME
    assert code == 0, "the engine in generate mode %s (exit code %r); its result: %s" % (why or "exited", code, said)

    result = json.loads((profile / RESULT_NAME).read_bytes().decode("utf-8"))
    assert set(result) == {"format", "ok", "error", "engine", "collections", "crlite_filter_hashes"}, sorted(result)
    assert result["format"] == 1 and result["ok"] is True and result["error"] is None, result
    build_id, version = _application_ini(ff)
    assert set(result["engine"]) == {"version", "build_id"} and result["engine"]["build_id"] == build_id and result["engine"]["version"] == version, result["engine"]
    assert set(result["collections"]) == {"intermediates", "onecrl", "cert-revocations"}, sorted(result["collections"])
    for name, stamp in (("intermediates", INTERMEDIATES_TS), ("onecrl", ONECRL_TS), ("cert-revocations", CRLITE_TS)):
        assert result["collections"][name]["collection_timestamp"] == stamp, (name, result["collections"][name])
    assert result["collections"]["cert-revocations"]["channel"] == "default", result["collections"]["cert-revocations"]
    full, delta = _crlite_file(FULL), _crlite_file(DELTA)
    assert sorted(result["crlite_filter_hashes"]) == sorted([hashlib.sha256(full).hexdigest(), hashlib.sha256(delta).hexdigest()]), result["crlite_filter_hashes"]

    state = profile / STATE_DIR
    assert (state / "data.safe.bin").is_file() and (state / "data.safe.bin").stat().st_size > 0, sorted(p.name for p in state.iterdir())
    assert (state / "crlite.filter").read_bytes() == full, "crlite.filter is not the bytes of the full filter"
    deltas = sorted(p for p in state.iterdir() if p.name.endswith(".delta"))
    assert [p.read_bytes() for p in deltas] == [delta], "the delta files of security_state/ are %s, not the one delta" % [p.name for p in deltas]

    # The same inputs through the core: its validation of the report and of the directory.
    assert _ready(ff, files, work).is_dir()


# --- a normal launch ---------------------------------------------------------------------------------------------------------------------------------------

class _Page(BaseHTTPRequestHandler):
    timeout = 5

    def do_GET(self):
        body = b"<!doctype html><title>page</title><p>ok"
        self.send_response(200)
        self.send_header("Content-Type", "text/html")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *args):
        pass


class _Server(LocalServer):
    def handle_error(self, request, client_address):
        pass  # a browser that refuses the certificate drops the connection in the middle of the handshake


@pytest.fixture
def http_page():
    server = _Server(("127.0.0.1", 0), _Page)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    try:
        yield "http://127.0.0.1:%d/" % server.server_address[1]
    finally:
        server.shutdown()
        server.server_close()


def _browse(ff, profile, url, prefs=None):
    """A launch of the wrapper on `profile`; its FIRST action is to go to `url`: (status of the response) or the error of the navigation."""
    from invisible_playwright import InvisiblePlaywright

    with InvisiblePlaywright(headless=True, seed=7, binary_path=ff, profile_dir=profile, extra_prefs=prefs) as context:
        page = context.new_page()
        try:
            response = page.goto(url, wait_until="domcontentloaded", timeout=60000)
        except Exception as exc:
            return exc
        return response.status


def test_a_normal_launch_declares_no_security_state_pref_and_imports_nothing(ff, inputs, tmp_path_factory, monkeypatch, http_page):
    ready = _ready(ff, inputs, tmp_path_factory.mktemp("ready-root"))
    monkeypatch.setenv("STEALTHFOX_SECURITY_STATE", str(ready))
    profile = tmp_path_factory.mktemp("normal") / "profile"
    outcome = _browse(ff, profile, http_page)
    assert outcome == 200, "the first page did not load: %r" % (outcome,)

    user_js = (profile / "user.js").read_bytes().decode("utf-8")
    assert [pref for pref in MODE_PREFS if pref in user_js] == [], "user.js of a normal launch names a pref of the generate mode"
    assert not (profile / RESULT_NAME).exists(), "a normal launch left a %s in the profile" % RESULT_NAME
    given = sorted(p.name for p in (ready / STATE_DIR).iterdir() if p.name == "crlite.filter" or p.name.endswith(".delta"))
    assert len(given) == 2, "the ready directory holds %s, not the full filter and a delta" % given
    for name in given:
        assert (profile / STATE_DIR / name).read_bytes() == (ready / STATE_DIR / name).read_bytes(), "%s of the profile is not the ready directory's bytes" % name


# --- a certificate revoked in a delta -----------------------------------------------------------------------------------------------------------------------

def _certificates(now):
    """A fresh root, the CA `CN=int` with Mozilla's default key (so with the public key the filters are keyed on) and two leaves for 127.0.0.1 that carry the serial and the
    SCT extension of Mozilla's revoked-in-delta and valid certificates: (root DER, int, {name: (leaf, leaf key)}, int key)."""
    x509, hashes, serialization, ec, name_oid = _x509()
    key_doc = json.loads((DATA / "security_state_default_key.json").read_bytes().decode("utf-8"))
    int_key = serialization.load_pem_private_key(key_doc["pem"].encode("ascii"), password=None)
    mozilla_int = x509.load_pem_x509_certificate(_crlite_file("int.pem"))
    public = serialization.Encoding.DER, serialization.PublicFormat.SubjectPublicKeyInfo
    assert int_key.public_key().public_bytes(*public) == mozilla_int.public_key().public_bytes(*public), \
        "the default key of %s is not the public key of Mozilla's int.pem" % key_doc["source"]

    def name(common):
        return x509.Name([x509.NameAttribute(name_oid.COMMON_NAME, common)])

    def builder(subject, issuer, public_key):
        return (x509.CertificateBuilder().subject_name(subject).issuer_name(issuer).public_key(public_key).not_valid_before(now - datetime.timedelta(days=1))
                .not_valid_after(now + datetime.timedelta(days=30)))

    ca_usage = x509.KeyUsage(digital_signature=False, content_commitment=False, key_encipherment=False, data_encipherment=False, key_agreement=False,
                             key_cert_sign=True, crl_sign=True, encipher_only=False, decipher_only=False)
    root_key = ec.generate_private_key(ec.SECP256R1())
    root = (builder(name("Security State Test Root"), name("Security State Test Root"), root_key.public_key()).serial_number(x509.random_serial_number())
            .add_extension(x509.BasicConstraints(ca=True, path_length=None), critical=True).add_extension(ca_usage, critical=True).sign(root_key, hashes.SHA256()))
    intermediate = (builder(mozilla_int.subject, root.subject, int_key.public_key()).serial_number(x509.random_serial_number())
                    .add_extension(x509.BasicConstraints(ca=True, path_length=0), critical=True).add_extension(ca_usage, critical=True).sign(root_key, hashes.SHA256()))
    assert intermediate.subject == mozilla_int.subject
    leaves = {}
    for label, source in (("revoked", REVOKED_NAME), ("valid", VALID_NAME)):
        mozilla = x509.load_pem_x509_certificate(_crlite_file(source))
        sct = mozilla.extensions.get_extension_for_oid(x509.oid.ExtensionOID.PRECERT_SIGNED_CERTIFICATE_TIMESTAMPS)
        key = ec.generate_private_key(ec.SECP256R1())
        leaf = (builder(name("localhost"), intermediate.subject, key.public_key()).serial_number(mozilla.serial_number)
                .add_extension(x509.BasicConstraints(ca=False, path_length=None), critical=True)
                .add_extension(x509.SubjectAlternativeName([x509.DNSName("localhost"), x509.IPAddress(ipaddress.ip_address("127.0.0.1"))]), critical=False)
                .add_extension(x509.ExtendedKeyUsage([x509.oid.ExtendedKeyUsageOID.SERVER_AUTH]), critical=False)
                .add_extension(x509.UnrecognizedExtension(sct.oid, sct.value.public_bytes()), critical=False).sign(int_key, hashes.SHA256()))
        copied = leaf.extensions.get_extension_for_oid(x509.oid.ExtensionOID.PRECERT_SIGNED_CERTIFICATE_TIMESTAMPS)
        assert copied.value.public_bytes() == sct.value.public_bytes() and leaf.serial_number == mozilla.serial_number, "the SCT list or the serial of %s was not copied" % source
        leaves[label] = (leaf, key)
    return root, intermediate, leaves


def _https_server(directory, label, leaf, key, intermediate):
    """An HTTPS server on 127.0.0.1 (a thread per connection) whose chain is the leaf and the intermediate; the handshake is made in the thread of the connection."""
    _x509_module, _hashes, serialization, _ec, _name_oid = _x509()
    chain = directory / (label + "-chain.pem")
    chain.write_bytes(leaf.public_bytes(serialization.Encoding.PEM) + intermediate.public_bytes(serialization.Encoding.PEM))
    key_file = directory / (label + "-key.pem")
    key_file.write_bytes(key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    context.load_cert_chain(str(chain), str(key_file))
    server = _Server(("127.0.0.1", 0), _Page)
    server.socket = context.wrap_socket(server.socket, server_side=True, do_handshake_on_connect=False)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    return server


# What `FF -xpcshell` runs to make `cert9.db` (the package has the shell but not the harness: a directory provider for the profile and profile-do-change, as the engine's own
# gate does). `add` trusts the root for SSL; `check` is a second process that only asks whether the profile trusts it.
_TRUST_JS = r"""
"use strict";
const env = name => Services.env.get(name);
const file = Cc["@mozilla.org/file/local;1"].createInstance(Ci.nsIFile);
file.initWithPath(env("ST_PROFILE"));
Services.dirsvc.QueryInterface(Ci.nsIDirectoryService).registerProvider({
  getFile(prop, persistent) {
    persistent.value = true;
    return ["ProfD", "ProfLD", "ProfDS", "ProfLDS"].includes(prop) ? file.clone() : null;
  },
  QueryInterface: ChromeUtils.generateQI(["nsIDirectoryServiceProvider"]),
});
Services.obs.notifyObservers(null, "profile-do-change", "security-state-test");
const certdb = Cc["@mozilla.org/security/x509certdb;1"].getService(Ci.nsIX509CertDB);
if (env("ST_MODE") == "add") {
  certdb.addCertFromBase64(env("ST_ROOT"), "CTu,,");
}
const root = certdb.constructX509FromBase64(env("ST_ROOT"));
const trusted = certdb.isCertTrusted(root, Ci.nsIX509Cert.CA_CERT, Ci.nsIX509CertDB.TRUSTED_SSL);
quit(trusted ? 0 : 3);
"""


def _trust_the_root(ff, profile, root_der, work):
    """`cert9.db` of `profile` with the root trusted for SSL, made BEFORE the browser starts, and read back by a second process."""
    script = work / "trust.js"
    script.write_text(_TRUST_JS, encoding="utf-8")
    profile.mkdir(parents=True, exist_ok=True)
    for mode in ("add", "check"):
        env = _engine_env(work)
        env.update(ST_MODE=mode, ST_PROFILE=str(profile), ST_ROOT=_b64(root_der))
        code, why = _run_to_the_end([ff, "-xpcshell", str(script)], env, work, 120)
        assert code == 0, "xpcshell (%s) %s, exit code %r: the root is not trusted in %s" % (mode, why or "exited", code, profile)
    assert (profile / "cert9.db").is_file(), "no cert9.db in the profile after the root was added"


def _refused(outcome):
    return isinstance(outcome, Exception) and SEC_ERROR_REVOKED_CERTIFICATE in str(outcome)


def test_a_certificate_revoked_in_a_delta_is_refused_at_the_first_navigation(ff, inputs, tmp_path_factory, monkeypatch):
    now = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    root, intermediate, leaves = _certificates(now)
    work = tmp_path_factory.mktemp("revoked")
    servers = {label: _https_server(work, label, leaf, key, intermediate) for label, (leaf, key) in leaves.items()}
    urls = {label: "https://127.0.0.1:%d/" % server.server_address[1] for label, server in servers.items()}
    # The copied SCTs are signed by Mozilla's test log, which Firefox does not know. With certificate transparency off Firefox hands the embedded timestamps to CRLite as they
    # are, which is what Mozilla's own test_crlite_filters.js does; this changes nothing of what is tested here: whether cert_storage has read the filters at the first navigation.
    prefs = {"security.pki.certificate_transparency.mode": 0}
    try:
        def profile_of(name):
            profile = work / name
            _trust_the_root(ff, profile, _der(root), work)
            return profile

        ready = _ready(ff, inputs, tmp_path_factory.mktemp("ready-root"))
        monkeypatch.setenv("STEALTHFOX_SECURITY_STATE", str(ready))
        outcome = _browse(ff, profile_of("with-data"), urls["revoked"], prefs)
        assert _refused(outcome), "the certificate revoked in the delta was not refused at the first navigation: %r" % (outcome,)

        # (a) the same engine, a certificate that is not revoked: it loads, so the refusal above is not a refusal of every certificate of the run.
        outcome = _browse(ff, profile_of("valid"), urls["valid"], prefs)
        assert outcome == 200, "the valid certificate was not accepted at the first navigation: %r" % (outcome,)

        # (b) a ready directory with no data: the revoked certificate loads, so the refusal comes from the security state.
        monkeypatch.setenv("STEALTHFOX_SECURITY_STATE", str(_a_ready_directory_with(work, "ready-without-data", state=None)))
        outcome = _browse(ff, profile_of("without-data"), urls["revoked"], prefs)
        assert outcome == 200, "with no security state the certificate must load (the refusal of the first launch is the state's): %r" % (outcome,)
    finally:
        for server in servers.values():
            server.shutdown()
            server.server_close()


# --- nothing to copy -----------------------------------------------------------------------------------------------------------------------------------

def test_a_launch_with_no_or_an_empty_security_state_starts(ff, tmp_path_factory, monkeypatch, http_page):
    for state in (None, "empty"):
        ready = _a_ready_directory_with(tmp_path_factory.mktemp("ready-root"), "ready", state=state)
        monkeypatch.setenv("STEALTHFOX_SECURITY_STATE", str(ready))
        outcome = _browse(ff, tmp_path_factory.mktemp("start") / "profile", http_page)
        assert outcome == 200, "with %s the first page did not load: %r" % ("no security_state/ directory" if state is None else "an empty security_state/ directory", outcome)
